      "id": 88,
      "pergunta": "Ao abrigo do teto, sua jornada de fé começava na sala de jantar. Na pequena célula cristã, dividia-se a refeição e durante elas os crentes conversavam, rezavam e liam cartas de correligionários residentes em locais diferentes do Império Romano (século II da Era Cristã). Esse ambiente garantia peculiar apoio emocional às experiências intensamente individuais que abrigava.\nSENNET, R. Carne e pedra. Rio de Janeiro: Record, 2008.\nUm motivo que explica a ambientação da prática descrita no texto encontra-se no(a)",
