      "id": 6,
      "pergunta": "QUESTÃO 06) O canto triste dos conquistados: os últimos dias de Tenochtitlán Nos caminhos jazem dardos quebrados; os cabelos estão espalhados.\nDestelhadas estão as casas, Vermelhas estão as águas, os rios, como se alguém as tivesse tingido, Nos escudos esteve nosso resguardo, mas os escudos não detêm a desolação...\nPINSKY, J. et al. História da América através de textos. São Paulo: Contexto, 2007 (fragmento). O texto é um registro asteca, cujo sentido está relacionado ao(à)",
