      "id": 76,
      "pergunta": "No sistema capitalista, as muitas manifestações de crise criam condições que forçam a algum tipo de racionalização. Em geral, essas crises periódicas têm o efeito de expandir a capacidade produtiva e de renovar as condições de acumulação. Podemos conceber cada crise como uma mudança do processo de acumulação para um nível novo e superior.\nHARVEY, D. A produção capitalista do espaço. A condição para a inclusão dos trabalhadores no novo processo produtivo descrito no texto é a",
