      "id": 85,
      "pergunta": "A Revolta da Vacina (1904) mostrou claramente o aspecto defensivo, desorganizado, fragmentado da ação popular. Não se negava o Estado, não se reivindicava participação nas decisões políticas; defendiam-se valores e direitos considerados acima da intervenção do Estado.\nCARVALHO, J. M. Os bestializados: o Rio de Janeiro e a República A mobilização analisada representou um alerta, na medida em que a ação popular questionava",
