      "id": 3,
      "pergunta": "QUESTÃO 03) Os dois principais rios que alimentavam o Mar de Aral, Amurdarya e Sydarya, mantiveram o nível e o volume do mar por muitos séculos. Entretanto, o projeto de estabelecer e expandir a produção de algodão irrigado aumentou a dependência de várias repúblicas da Ásia Central da irrigação e monocultura. O aumento da demanda resultou no desvio crescente de água para a irrigação, acarretando redução drástica do volume de tributários do Mar de Aral. Foi criado na Ásia Central um novo deserto, com mais de 5 milhões de hectares, como resultado da redução em volume. TUNDISI, J. G. Água no século XXI: enfrentando a escassez. São Carlos: Rima, 2003.\nA intensa interferência humana na região descrita provocou o surgimento de uma área desértica em decorrência da",
