      "id": 21,
      "pergunta": "QUESTÃO 21) Pois quem seria tão inútil ou indolente a ponto de não desejar saber como e sob que espécie de constituição os romanos conseguiram em menos de cinquenta e três anos submeter quase todo o mundo habitado ao seu governo exclusivo — fato nunca antes ocorrido? Ou, em outras palavras, quem seria tão apaixonadamente devotado a outros espetáculos ou estudos a ponto de considerar qualquer outro objetivo mais importante que a aquisição desse conhecimento? POLÍBIO. História. Brasília: Editora UnB, 1985.\nA experiência a que se refere o historiador Políbio, nesse texto escrito no século II a.C., é a",
