      "pergunta": "QUESTÃO 30) Os movimentos de massa constituem-se no deslocamento de material (solo e rocha) vertente abaixo pela influência da gravidade. As condições que favorecem os movimentos de massa dependem principalmente da estrutura geológica, da declividade da vertente, do regime de chuvas, da perda de vegetação e da atividade antrópica.\nBIGARELLA, J. J. Estrutura e origem das paisagens tropicais e subtropicais. Em relação ao processo descrito, sua ocorrência é minimizada em locais onde há",
