      "id": 65,
      "pergunta": "QUESTÃO 60) Procuramos demonstrar que o desenvolvimento pode ser visto como um processo de expansão das liberdades reais que as pessoas desfrutam. O enfoque nas liberdades humanas contrasta com visões mais restritas de desenvolvimento, como as que identiﬁcam desenvolvimento com crescimento do Produto Nacional Bruto, ou industrialização. O crescimento do PNB pode ser muito importante como um meio de expandir as liberdades. Mas as liberdades dependem também de outros determinantes, como os serviços de educação e saúde e os direitos civis.\nSEN, A. Desenvolvimento como liberdade. São Paulo: Cia. das Letras, 2010.\nA concepção de desenvolvimento proposta no texto fundamenta-se no vínculo entre",
