      "pergunta": "QUESTÃO 62) O New Deal visa restabelecer o equilíbrio entre o custo de produção e o preço, entre a cidade e o campo, entre os preços agrícolas e os preços industriais, reativar o mercado interno — o único que é importante —, pelo controle de preços e da produção, pela revalorização dos salários e do poder aquisitivo das massas, isto é, dos lavradores e operários, e pela regulamentação das condições de emprego.\nCROUZET, M. Os Estados perante a crise. In: História geral das civilizações. Tendo como referência os condicionantes históricos do entreguerras, as medidas governamentais descritas objetivavam",
