      "id": 87,
      "pergunta": "QUESTÃO 82) O instituto popular, de acordo com o exame da razão, fez da ﬁgura do alferes Xavier o principal dos inconﬁdentes, e colocou os seus parceiros a meia ração de glória. Merecem, decerto, a nossa estima aqueles outros; eram patriotas. Mas o que se ofereceu a carregar com os pecadores de Israel, o que chorou de alegria quando viu comutada a pena de morte dos seus companheiros, pena que só ia ser executada nele, o enforcado, o esquartejado, o decapitado, esse tem de receber o prêmio na proporção do martírio, e ganhar por todos, visto que pagou por todos.\nASSIS, M. Gazeta de Notícias, n. 114, 24 abr. 1892.\nNo processo de transição para a República, a narrativa machadiana sobre a Inconﬁdência Mineira associa",
