      "id": 2025079,
      "pergunta": "A missão dos governantes consiste em promover a felicidade da sociedade, punindo e recompensando. A parte da missão de governo que consiste em punir constitui mais particularmente o objeto da lei penal. A obrigatoriedade ou necessidade de punir uma ação é proporcional à medida em tal ação tende a perturbar a felicidade e a medida que a tendência de inferido ato é perniciosa. A felicidade consiste naquilo que já vimos, ou seja, em desfrutar prazeres e em evitar lesões de dores. BENTHAM, J. Uma introdução aos princípios da moral e da legislação. São Paulo: Abril Cultural, 1974 (adaptado).\nQual perspectiva de justiça emerge da relação, estabelecida no texto, entre punição e felicidade?",
