      "id": 2025090,
      "pergunta": "Em 1914, uma expedição estudantil saiu da Rússia em direção à América do Sul, sendo considerada a segunda campanha científica da história no continente depois da longa viagem do barão Langsdorff para o interior do Brasil na primeira metade do século XIX. O empreendimento foi enviado pelo Museu de Antropologia e Etnografia de São Petersburgo e integrado por cinco jovens cientistas, sendo dois zoólogos, dois etnógrafos e um antropólogo, cujo objetivo era a coleta de material de valor biológico e etnográfico para compor coleções nas instituições que participaram de seu financiamento. A expedição passou por países como Brasil, Paraguai e Argentina, resultando em amplo material museológico e algumas publicações, além dos objetos coletados. CARNEIRO, L. A. F. A Rússia do Brasil no início do século XX. Rio de Janeiro: Universidade do Estado do Rio, 2015 (adaptado).\nAlém do significado científico, o evento mencionado conectava-se a um projeto nacionalista de caráter",
