      "id": 2009046,
      "pergunta": "O Egito é visitado anualmente por milhões de turistas de todos os quadrantes do planeta, desejosos de ver com os próprios olhos a grandiosidade do poder esculpida em pedra há milênios: as pirâmides de Gizeh, as tumbas do Vale dos Reis e os numerosos templos construídos ao longo do Nilo.\nO que hoje se transformou em atração turística era, no passado, interpretado de forma muito diferente, pois",
