      "id": 2018075,
      "pergunta": "Os países industriais adotaram uma concepção diferente das relações familiares e do lugar da fecundidade na vida familiar e social. A preocupação de garantir uma\ntransmissão integral das vantagens econômicas e sociais adquiridas tem como resultado uma ação voluntária de limitação do número de nascimentos.\nGEORGE, P Panorama do mundo atual. São Paulo: Difusão Européia do Livro, 1968 (adaptado).\nEm meados do século XX, o fenômeno social descrito contribuiu para o processo europeu de",
